import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import * as Diff from 'diff';
import './DiffChecker.css';

const DiffChecker = () => {
  const [originalText, setOriginalText] = useState('');
  const [changedText, setChangedText] = useState('');
  const [showDiff, setShowDiff] = useState(false);
  const [diffResults, setDiffResults] = useState({ original: [], changed: [] });

  const findDifference = () => {
    const diff = Diff.diffLines(originalText, changedText);

    const originalLines = [];
    const changedLines = [];

    diff.forEach((part) => {
      const lines = part.value.split('\n').filter((line, idx, arr) => {
        // Keep empty lines except the last one if it's empty
        return idx < arr.length - 1 || line !== '';
      });

      lines.forEach((line) => {
        if (part.added) {
          // Added in changed text
          changedLines.push({ text: line, type: 'added' });
        } else if (part.removed) {
          // Removed from original text
          originalLines.push({ text: line, type: 'removed' });
        } else {
          // Unchanged
          originalLines.push({ text: line, type: 'unchanged' });
          changedLines.push({ text: line, type: 'unchanged' });
        }
      });
    });

    setDiffResults({ original: originalLines, changed: changedLines });
    setShowDiff(true);
  };

  const clearAll = () => {
    setOriginalText('');
    setChangedText('');
    setShowDiff(false);
    setDiffResults({ original: [], changed: [] });
  };

  const renderDiffLine = (line, index) => {
    const className = `diff-line ${line.type}`;
    return (
      <div key={index} className={className}>
        <span className="line-number">{index + 1}</span>
        <span className="line-content">{line.text || '\u00A0'}</span>
      </div>
    );
  };

  return (
    <div className="diff-checker-page">
      <div className="diff-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>Diff Checker</h1>
        <p>Compare and find differences between two texts</p>
      </div>

      <div className="diff-container">
        {!showDiff ? (
          <div className="input-section">
            <div className="text-input-container">
              <div className="text-input-box">
                <h3>Original Text</h3>
                <textarea
                  value={originalText}
                  onChange={(e) => setOriginalText(e.target.value)}
                  placeholder="Paste your original text here..."
                  className="text-area"
                />
              </div>
              <div className="text-input-box">
                <h3>Changed Text</h3>
                <textarea
                  value={changedText}
                  onChange={(e) => setChangedText(e.target.value)}
                  placeholder="Paste your changed text here..."
                  className="text-area"
                />
              </div>
            </div>
            <div className="button-group">
              <button onClick={findDifference} className="find-diff-button">
                Find Difference
              </button>
              <button onClick={clearAll} className="clear-button">
                Clear All
              </button>
            </div>
          </div>
        ) : (
          <div className="results-section">
            <div className="results-header">
              <h2>Comparison Results</h2>
              <button onClick={() => setShowDiff(false)} className="edit-button">
                ← Edit Texts
              </button>
            </div>
            <div className="legend">
              <span className="legend-item">
                <span className="legend-color removed-color"></span>
                Deletions
              </span>
              <span className="legend-item">
                <span className="legend-color added-color"></span>
                Additions
              </span>
            </div>
            <div className="diff-results">
              <div className="diff-column">
                <h3>Original Text</h3>
                <div className="diff-content">
                  {diffResults.original.map((line, index) => renderDiffLine(line, index))}
                </div>
              </div>
              <div className="diff-column">
                <h3>Changed Text</h3>
                <div className="diff-content">
                  {diffResults.changed.map((line, index) => renderDiffLine(line, index))}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DiffChecker;
